ords.export'), ('housekeeping.settings.edit'), ('housekeeping.records.view'), ('housekeeping.records.export'), ('laundry.settings.edit'), ('laundry.records.view'), ('laundry.records.export'), ('security-incidents.settings.edit'), ('security-incidents.records.view'), ('security-incidents.records.export'), ('lost-found.settings.edit'), ('lost-found.records.view'), ('lost-found.records.export'), ('fleet-transport.settings.edit'), ('fleet-transport.records.view'), ('fleet-transport.records.export'), ('knowledge-base.settings.edit'), ('knowledge-base.records.view'), ('knowledge-base.records.export'), ('meetings.settings.edit'), ('meetings.records.view'), ('meetings.records.export'), ('surveys-polls.settings.edit'), ('surveys-polls.records.view'), ('surveys-polls.records.export'), ('company-calendar.settings.edit'), ('company-calendar.records.view'), ('company-calendar.records.export'), ('corporate-accounts.settings.edit'), ('corporate-accounts.records.view'), ('corporate-accounts.records.export'), ('guest-feedback.settings.edit'), ('guest-feedback.records.view'), ('guest-feedback.records.export'), ('loyalty.settings.edit'), ('loyalty.records.view'), ('loyalty.records.export'), ('campaigns.settings.edit'), ('campaigns.records.view'), ('campaigns.records.export'), ('promotions-vouchers.settings.edit'), ('promotions-vouchers.records.view'), ('promotions-vouchers.records.export'), ('guest-requests.settings.edit'), ('guest-requests.records.view'), ('guest-requests.records.export'), ('kitchen-display.settings.edit'), ('kitchen-display.records.view'), ('kitchen-display.records.export'), ('buffet.settings.edit'), ('buffet.records.view'), ('buffet.records.export'), ('pricing-tax.settings.edit'), ('pricing-tax.records.view'), ('pricing-tax.records.export'), ('receipts-invoicing.settings.edit'), ('receipts-invoicing.records.view'), ('receipts-invoicing.records.export'), ('cash-up.settings.edit'), ('cash-up.records.view'), ('cash-up.records.export'), ('accounting-export.settings.edi