INSERT INTO "roles"."role_permissions" ("role_id","permission_key","scope") SELECT r."id", p.key, 'own' FROM "roles"."roles" r CROSS JOIN (VALUES ('petty-cash.records.view'), ('petty-cash.records.create'), ('training.records.view'), ('training.records.create'), ('surveys-polls.records.view'), ('surveys-polls.records.create'), ('visitor-management.records.view'), ('visitor-management.records.create'), ('workflow-approvals.records.view'), ('workflow-approvals.records.create'), ('forms-builder.records.view'), ('forms-builder.records.create'), ('access-zones.records.view'), ('access-zones.records.create'), ('security-incidents.records.view'), ('security-incidents.records.create'), ('lost-found.records.view'), ('lost-found.records.create'), ('performance.records.view'), ('performance.records.create'), ('discipline.records.view'), ('discipline.records.create'), ('onboarding-exit.records.view'), ('onboarding-exit.records.create'), ('staff-welfare.records.view'), ('staff-welfare.records.create'), ('leave.records.view'), ('leave.records.create'), ('shifts-rosters.records.view'), ('shifts-rosters.records.create')) AS p(key) WHERE r."id" = 'role_staff-base' ON CONFLICT DO NOTHING;
