INSERT INTO "roles"."role_permissions" ("role_id","permission_key","scope") SELECT r."id", p.key, 'all' FROM "roles"."roles" r CROSS JOIN (VALUES ('company-calendar.records.view')) AS p(key) WHERE r."id" = 'role_staff-base' ON CONFLICT DO NOTHING;
