INSERT INTO "roles"."role_permissions" ("role_id","permission_key","scope") SELECT r."id", p.key, 'own' FROM "roles"."roles" r CROSS JOIN (VALUES ('lost-found.records.view'), ('lost-found.records.create'), ('guest-feedback.records.view'), ('guest-feedback.records.create'), ('guest-requests.records.view'), ('guest-requests.records.create'), ('laundry.records.view'), ('laundry.records.create'), ('fleet-transport.records.view'), ('fleet-transport.records.create'), ('buffet.records.view'), ('buffet.records.create'), ('promotions-vouchers.records.view'), ('promotions-vouchers.records.create'), ('loyalty.records.view'), ('loyalty.records.create')) AS p(key) WHERE r."id" = 'role_guest' ON CONFLICT DO NOTHING;
